// GENERATED by scripts/sync-skill.mjs from prototype/limbmesh.js. Edit the prototype, not this copy.
// Skinned-looking 2D limb/torso outlines from joint positions. Pure geometry.
//
// Instead of one rigid capsule per bone (which shows a visible pivot "ball" at
// every elbow/knee), a limb is ONE continuous outline through root -> joint ->
// end. The outer side of the bend gets a round join (volume preserved), the
// inner side gets a sharp crease at the intersection of the two offset edges
// (skin folds there), and the width tapers/bulges along the limb.
// All points are { x, y } in whatever space the inputs are in.

const EPS = 1e-9;

function sub(a, b) {
  return { x: a.x - b.x, y: a.y - b.y };
}
function len(v) {
  return Math.hypot(v.x, v.y);
}
function norm(v) {
  const l = len(v);
  return l < EPS ? { x: 0, y: 1 } : { x: v.x / l, y: v.y / l };
}
/** Left normal of a direction (rotate +90 degrees in the x-right, y-down plane). */
function leftOf(d) {
  return { x: -d.y, y: d.x };
}

/**
 * Width at parameter t in [0,1] of one segment: linear taper plus a sine bulge
 * (muscle volume). bulge is a fraction of the start width.
 */
export function segmentWidth(w0, w1, t, bulge = 0) {
  return w0 + (w1 - w0) * t + bulge * w0 * Math.sin(Math.PI * t);
}

/** Signed bend angle at joint b of the polyline a-b-c (positive = turning toward the left normal). */
export function bendAngle(a, b, c) {
  const d1 = norm(sub(b, a));
  const d2 = norm(sub(c, b));
  return Math.atan2(d1.x * d2.y - d1.y * d2.x, d1.x * d2.x + d1.y * d2.y);
}

/**
 * Intersection of lines p + t*d and q + u*e. Returns { t, u } or null when parallel.
 */
export function lineIntersect(p, d, q, e) {
  const den = d.x * e.y - d.y * e.x;
  if (Math.abs(den) < 1e-6) return null;
  const w = sub(q, p);
  return { t: (w.x * e.y - w.y * e.x) / den, u: (w.x * d.y - w.y * d.x) / den };
}

/**
 * Outline of a two-segment limb.
 * a, b, c: root, joint (elbow/knee), end (wrist/ankle).
 * w = [wRoot, wJoint, wEnd] full widths. opts.bulge = [upper, lower] (fraction).
 * opts.samples = points per segment (>= 2).
 * Returns { left, right, tipCap, rootCap, crease, bend } where left/right run
 * root -> end, tipCap runs from left end to right end around c, and rootCap
 * runs from right root to left root around a. `crease` is null when the limb is
 * (nearly) straight, else { x, y, side, depth } (depth 0..1 by bend amount).
 */
export function limbOutline(a, b, c, w, opts = {}) {
  const n = Math.max(2, opts.samples ?? 6);
  const [bu, bl] = opts.bulge ?? [0, 0];
  const d1 = norm(sub(b, a));
  const d2 = norm(sub(c, b));
  const n1 = leftOf(d1);
  const n2 = leftOf(d2);
  const L1 = len(sub(b, a));
  const L2 = len(sub(c, b));
  const bend = bendAngle(a, b, c);
  const innerSign = bend > 0 ? 1 : -1; // +1: left side is the inside of the bend
  const bent = Math.abs(bend) > 0.06;
  const halfJ = w[1] / 2;

  const seg = (p0, d, nrm, L, w0, w1, bulge, sign, from, to) => {
    const out = [];
    for (let i = 0; i <= n; i++) {
      const t = from + ((to - from) * i) / n;
      const hw = segmentWidth(w0, w1, t, bulge) / 2;
      out.push({ x: p0.x + d.x * L * t + nrm.x * hw * sign, y: p0.y + d.y * L * t + nrm.y * hw * sign });
    }
    return out;
  };

  const side = (sign) => {
    if (bent && sign === innerSign) {
      // inner side: straight offset edges meeting at a crease point
      const p = { x: b.x + n1.x * halfJ * sign, y: b.y + n1.y * halfJ * sign };
      const q = { x: b.x + n2.x * halfJ * sign, y: b.y + n2.y * halfJ * sign };
      const hit = lineIntersect(p, d1, q, d2);
      // t < 0 means the crease sits before the joint along segment 1
      const t1 = hit ? Math.max(-L1 * 0.9, Math.min(0, hit.t)) : 0;
      const u2 = hit ? Math.min(L2 * 0.9, Math.max(0, hit.u)) : 0;
      const f1 = 1 + t1 / Math.max(L1, EPS);
      const f2 = u2 / Math.max(L2, EPS);
      const upper = seg(a, d1, n1, L1, w[0], w[1], bu, sign, 0, f1);
      const lower = seg(b, d2, n2, L2, w[1], w[2], bl, sign, f2, 1);
      const crease = hit
        ? { x: p.x + d1.x * t1, y: p.y + d1.y * t1 }
        : { x: (upper[upper.length - 1].x + lower[0].x) / 2, y: (upper[upper.length - 1].y + lower[0].y) / 2 };
      return { pts: [...upper.slice(0, -1), crease, ...lower.slice(1)], crease };
    }
    // outer side (or straight): offset edges joined by an arc around the joint
    const upper = seg(a, d1, n1, L1, w[0], w[1], bu, sign, 0, 1);
    const lower = seg(b, d2, n2, L2, w[1], w[2], bl, sign, 0, 1);
    const arc = [];
    if (bent) {
      const a0 = Math.atan2(n1.y * sign, n1.x * sign);
      let a1 = Math.atan2(n2.y * sign, n2.x * sign);
      let da = a1 - a0;
      while (da > Math.PI) da -= 2 * Math.PI;
      while (da < -Math.PI) da += 2 * Math.PI;
      a1 = a0 + da;
      const steps = Math.max(2, Math.ceil(Math.abs(da) / 0.3));
      for (let i = 1; i < steps; i++) {
        const ang = a0 + (da * i) / steps;
        arc.push({ x: b.x + Math.cos(ang) * halfJ, y: b.y + Math.sin(ang) * halfJ });
      }
    }
    return { pts: [...upper, ...arc, ...lower.slice(1)], crease: null };
  };

  const L = side(1);
  const R = side(-1);
  const cap = (center, from, dir, r, steps = 5) => {
    // semicircle from `from` side normal, bulging along dir
    const out = [];
    const a0 = Math.atan2(from.y, from.x);
    const s = from.x * dir.y - from.y * dir.x > 0 ? 1 : -1;
    for (let i = 1; i < steps; i++) {
      const ang = a0 + (s * Math.PI * i) / steps;
      out.push({ x: center.x + Math.cos(ang) * r, y: center.y + Math.sin(ang) * r });
    }
    return out;
  };
  const tipCap = cap(c, n2, d2, w[2] / 2);
  const rootCap = cap(a, { x: -n1.x, y: -n1.y }, { x: -d1.x, y: -d1.y }, w[0] / 2);
  const cr = L.crease || R.crease;
  return {
    left: L.pts,
    right: R.pts,
    tipCap,
    rootCap,
    crease: cr ? { x: cr.x, y: cr.y, side: innerSign, depth: Math.min(1, Math.abs(bend) / 1.6) } : null,
    bend,
  };
}

/** Closed polygon (root-left -> end -> root-right -> root cap). */
export function limbPolygon(o, withRootCap = true) {
  return [...o.left, ...o.tipCap, ...o.right.slice().reverse(), ...(withRootCap ? o.rootCap : [])];
}

/** Open stroke path that skips the root cap, so the limb merges into the body it grows from. */
export function limbStrokePath(o) {
  return [...o.left, ...o.tipCap, ...o.right.slice().reverse()];
}

/** Point on the quadratic through p0, p1 (passed through at t=0.5), p2. */
export function throughQuad(p0, p1, p2, t) {
  const cx = 2 * p1.x - (p0.x + p2.x) / 2;
  const cy = 2 * p1.y - (p0.y + p2.y) / 2;
  const u = 1 - t;
  return { x: u * u * p0.x + 2 * u * t * cx + t * t * p2.x, y: u * u * p0.y + 2 * u * t * cy + t * t * p2.y };
}

/** Piecewise-linear profile lookup: profile = [[t, value], ...] sorted by t. */
export function profileAt(profile, t) {
  if (t <= profile[0][0]) return profile[0][1];
  for (let i = 0; i < profile.length - 1; i++) {
    const [t0, v0] = profile[i];
    const [t1, v1] = profile[i + 1];
    if (t <= t1) {
      const u = (t - t0) / Math.max(t1 - t0, EPS);
      const s = u * u * (3 - 2 * u);
      return v0 + (v1 - v0) * s;
    }
  }
  return profile[profile.length - 1][1];
}

/**
 * Torso outline that BENDS with the spine instead of being one rigid shape.
 * p0 = hip centre, p1 = waist (spine/chest joint), p2 = neck base.
 * front/back: half-width profiles [[t, w], ...] for the +normal (front) and
 * -normal (back) sides; t runs hips (0) -> neck (1).
 * Returns { front, back, top, center } point arrays (front/back run hips -> neck).
 */
export function torsoOutline(p0, p1, p2, front, back, opts = {}) {
  const n = Math.max(4, opts.samples ?? 10);
  const breath = opts.breath ?? 0;
  const center = [];
  const F = [];
  const B = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const p = throughQuad(p0, p1, p2, t);
    const q = throughQuad(p0, p1, p2, Math.min(1, t + 0.02));
    const r = throughQuad(p0, p1, p2, Math.max(0, t - 0.02));
    const d = norm(sub(q, r));
    // y-down, going up the body: the left normal points to the character's front (+x)
    const nl = leftOf(d);
    const chest = 1 + breath * Math.max(0, Math.sin(Math.PI * Math.min(1, Math.max(0, (t - 0.45) / 0.55))));
    const wf = profileAt(front, t) * chest;
    const wb = profileAt(back, t) * (1 + (chest - 1) * 0.5);
    center.push(p);
    F.push({ x: p.x + nl.x * wf, y: p.y + nl.y * wf });
    B.push({ x: p.x - nl.x * wb, y: p.y - nl.y * wb });
  }
  // shoulders: a rounded top from the front edge to the back edge
  const fTop = F[n];
  const bTop = B[n];
  const up = norm(sub(p2, p1));
  const lift = opts.shoulderLift ?? 2.5;
  const top = [];
  for (let i = 1; i < 6; i++) {
    const t = i / 6;
    const s = Math.sin(Math.PI * t);
    top.push({ x: fTop.x + (bTop.x - fTop.x) * t + up.x * lift * s, y: fTop.y + (bTop.y - fTop.y) * t + up.y * lift * s });
  }
  return { front: F, back: B, top, center };
}

/** Closed torso polygon. */
export function torsoPolygon(o) {
  return [...o.front, ...o.top, ...o.back.slice().reverse()];
}

/**
 * Smear (motion-blur "drag" frame) between a previous and current end position.
 * Returns null when the move is shorter than minDist, else a tapered polygon:
 * thin at the old position, full radius r at the new one.
 */
export function smearPolygon(prev, cur, r, minDist) {
  const d = sub(cur, prev);
  const L = len(d);
  if (!(L >= minDist) || r <= 0) return null;
  const u = norm(d);
  const nl = leftOf(u);
  const tail = r * 0.25;
  return [
    { x: prev.x + nl.x * tail, y: prev.y + nl.y * tail },
    { x: cur.x + nl.x * r, y: cur.y + nl.y * r },
    { x: cur.x + u.x * r * 0.6, y: cur.y + u.y * r * 0.6 },
    { x: cur.x - nl.x * r, y: cur.y - nl.y * r },
    { x: prev.x - nl.x * tail, y: prev.y - nl.y * tail },
  ];
}
